changed=[name for name in om if ast.dump(om[name])"'!=ast.dump(nm[name])]
assert set(changed)=={'"'__init__','forward'},changed
# Training loss, row-local gates, source ownership and compression methods are exact copies.
assert hashlib.sha256((root/'baseline_reference.py').read_bytes()).hexdigest()=='f4b473cbacf60d72cff90f3721ad754dd617ee6065fe3fca2fc9cd4be2b25c36'
